import sys, os; sys.path.insert(0, os.path.dirname(os.path.dirname(os.path.abspath(__file__)))); os.chdir(os.path.dirname(os.path.dirname(os.path.abspath(__file__)))+"/out")
from h18 import *
"""Capacity: points per role on cards (Monthly) and the Capacity dashboard (months at a glance, what to fix, room per track, team with leave and leaving), warning before a move, order (needs), settings, executive view. Fake database only."""
R=[]
def ok(n,c): R.append((n,bool(c))); print(('PASS ' if c else 'FAIL ')+n)
def add(P,mo,text):
    c=P.locator('.mdcol[data-mo="%s"]'%mo); c.locator('.mdopen').click(); ta=c.locator('.mdadd textarea'); ta.fill(text); ta.press('Enter'); P.wait_for_timeout(500); P.keyboard.press('Escape'); P.wait_for_timeout(250)
def card(P,t): return P.locator('.mdcard:has-text("%s")'%t).first
def open_points(P,t): card(P,t).locator('.kebab').click(); P.locator('#ctx .mi:has-text("Points and people")').click(); P.wait_for_timeout(300)
def points(P,t,vals,needs=None):
    open_points(P,t)
    for k,ppl in vals.items():
        P.click('#xdlg .ptrack[data-k="%s"]'%k)
        for n,v in ppl.items():
            r=P.locator('#xdlg .pperson[data-track="%s"][data-name="%s"]'%(k,n)); r.locator('input[type=checkbox]').check(); r.locator('select').select_option(str(v))
    if needs is not None: P.locator('#xdlg input[aria-label="Needs card"]').fill(needs)
    P.click('#xdlg button:text-is("Save")'); P.wait_for_timeout(500)
MI={'2026-10':0,'2026-11':1,'2026-12':2,'2027-01':3}
def dash(P): P.click('#nav button[data-p="capacity"]'); P.wait_for_timeout(500)
def meter(P,mo,lane):
    dash(P); return P.locator('#cproom tr[data-lane="%s"] td'%lane).nth(MI[mo]).locator('b').inner_text().strip()
def back(P): P.click('#nav button[data-p="monthly"]'); P.wait_for_timeout(500)
with sync_playwright() as pw:
    b=pw.chromium.launch(); ctx=mkctx(b); ctx.clock.set_fixed_time("2026-10-20T10:00:00"); errs=[]
    A=newpage(ctx,errs); signup(A,'Admin','adm@x.com'); E=newpage(ctx,errs); signup(E,'Exec','exec@x.com')
    A.click('#nav button[data-p="admin"]'); A.wait_for_timeout(700); A.locator('#permissions .permuser:has-text("Exec")').click(); A.wait_for_timeout(300)
    A.click('#permissions button:text-is("Approve with these permissions")'); A.wait_for_timeout(800)
    A.click('#nav button[data-p="monthly"]'); A.wait_for_timeout(900)
    add(A,'2026-11','alpha'); add(A,'2026-11','beta'); add(A,'2026-10','gamma')
    ok('C0 Monthly columns no longer carry the capacity meters', A.locator('.caprow').count()==0 and A.locator('#mdtocap').count()==1)
    dash(A)
    ok('C1 the dashboard lists the seven tracks across four months', A.locator('#cproom tbody tr').count()==7 and A.locator('#cproom thead th').count()==5 and A.locator('.cptile').count()==4 and A.locator('#cproom tbody th').all_inner_texts()==['AI','Full Stack FE','Full Stack Mobile','BE','PMs','Design','Quality'])
    ok('C2 BE capacity of November = 4 people x 8 less 30% = 22.4', meter(A,'2026-11','be')=='0 / 22.4')
    ok('C2b with nothing to fix the page says so', A.locator('#cpnone').count()==1); back(A)
    open_points(A,'alpha')
    ok('P1 the dialog starts with the tracks only: no people are shown yet', A.locator('#xdlg .ptrack').count()==7 and A.locator('#xdlg .ptsec:visible').count()==0)
    A.click('#xdlg .ptrack[data-k="be"]'); A.wait_for_timeout(150)
    ok('P2 choosing a track shows the people of that track only', A.locator('#xdlg .ptsec:visible').count()==1 and A.locator('#xdlg .pperson[data-track="be"]:visible').all_inner_texts()==['Soliman\npoints','Wardany\npoints','Hosieny\npoints','Hamid\npoints'] or A.locator('#xdlg .pperson[data-track="be"]:visible').count()==4)
    ok('P3 a person\'s points are disabled until the name is ticked', A.locator('#xdlg .pperson[data-name="Soliman"] select').is_disabled())
    A.locator('#xdlg .pperson[data-name="Soliman"] input').check(); A.click('#xdlg button:text-is("Save")'); A.wait_for_timeout(200)
    ok('P4 a ticked person without points is refused with a clear message', 'Give Soliman some points' in A.locator('#xdlg').inner_text())
    A.locator('#xdlg .pperson[data-name="Soliman"] input').uncheck(); A.click('#xdlg button:text-is("Save")'); A.wait_for_timeout(200)
    ok('P5 a chosen track with nobody ticked is refused', 'Pick at least one person for BE' in A.locator('#xdlg').inner_text())
    A.click('#xdlg button:text-is("Cancel")'); A.wait_for_timeout(200)
    points(A,'alpha',{'be':{'Soliman':8,'Wardany':5},'fe':{'Amal':5}}); points(A,'beta',{'be':{'Hosieny':8}}); points(A,'gamma',{'be':{'Hamid':8}})
    stored=A.evaluate("()=>{const d=JSON.parse(localStorage.getItem('fk3')).reports.mo202611; const l=d.lines.find(x=>x.t==='alpha'); return JSON.stringify({pts:l.pts,who:l.who})}")
    ok('P6 the card keeps who and the total per track (BE 8 + 5 = 13)', '"be":13' in stored and '"fe":5' in stored and '"Soliman":8' in stored and '"Wardany":5' in stored)
    ok('P7 the card tooltip names the people', 'Soliman 8' in card(A,'alpha').locator('.mdpts').get_attribute('title'))
    open_points(A,'alpha')
    ok('P8 reopening shows the saved tracks, people and points', A.locator('#xdlg .ptrack[aria-pressed="true"]').count()==2 and A.locator('#xdlg .pperson[data-name="Soliman"] select').input_value()=='8' and A.locator('#xdlg .pperson[data-name="Soliman"] input').is_checked())
    A.click('#xdlg button:text-is("Cancel")'); A.wait_for_timeout(200)
    ok('C3 the room table adds up the points of the cards (21 of 22.4)', meter(A,'2026-11','be')=='21 / 22.4' and A.locator('#cproom tr[data-lane="fe"] td').nth(1).locator('b').inner_text()=='5 / 16.8')
    ok('C3b November tile says it is almost full', 'almost full' in A.locator('.cptile[data-mo="2026-11"]').inner_text() and 'Tight' in A.locator('.cptile[data-mo="2026-11"]').inner_text()); back(A)
    ok('C4 the card shows its points', card(A,'alpha').locator('.mdpts').inner_text()=='18 pts')
    card(A,'gamma').locator('.kebab').click(); A.locator('#ctx .mi:text-is("November 2026")').click(); A.wait_for_timeout(500)
    ok('C5 moving a card that breaks BE capacity warns first', 'BE would be 29 of 22.4' in A.locator('#xdlg').inner_text())
    A.click('#xdlg button:text-is("Cancel")'); A.wait_for_timeout(300)
    ok('C6 Cancel leaves the card where it was', A.locator('.mdcol[data-mo="2026-10"] .mdcard:has-text("gamma")').count()==1)
    card(A,'gamma').locator('.kebab').click(); A.locator('#ctx .mi:text-is("November 2026")').click(); A.wait_for_timeout(400); A.click('#xdlg button:text-is("Move anyway")'); A.wait_for_timeout(600)
    ok('C7 Move anyway moves it and the dashboard shows November over', A.locator('.mdcol[data-mo="2026-11"] .mdcard:has-text("gamma")').count()==1 and meter(A,'2026-11','be')=='29 / 22.4' and A.locator('#cproom td.cp-over').count()==1 and 'Over' in A.locator('.cptile[data-mo="2026-11"]').inner_text())
    t=A.locator('#cp-fix').inner_text()
    ok('C8 What needs fixing names the track and how much it is over', 'BE is over by 6.6 points' in t and A.locator('#cpnone').count()==0)
    ok('C8b it suggests a card to move to a month where it fits', 'You could move "' in t and 'It fits there' in t and 'December 2026' in t)
    A.locator('#cp-fix .cpitem button').first.click(); A.wait_for_timeout(500)
    ok('C8c the button takes you to Monthly', A.locator('#pg-monthly').is_visible() and not A.locator('#pg-capacity').is_visible())
    # order: delta (October) needs beta (November)
    add(A,'2026-10','delta')
    beta_id=A.evaluate("()=>{const d=JSON.parse(localStorage.getItem('fk3')).reports.mo202611; const l=d.lines.find(x=>x.t==='beta'); return (l.k==='daycare'?'DC':'??')+'#'+l.no}")
    points(A,'delta',{'qa':{'Zahran':2}},needs=beta_id)
    ok('C9 a card shows what it needs', 'Needs' in card(A,'delta').inner_text())
    dash(A); t=A.locator('#cp-fix').inner_text()
    ok('C10 the dashboard lists an order problem (needs a card planned later)', 'Card order' in t and 'planned later' in t)
    back(A); card(A,'beta').locator('.kebab').click(); A.locator('#ctx .mi:text-is("Back to backlog")').click(); A.wait_for_timeout(500)
    ok('C11 moving the needed card to the backlog needs no capacity warning (not a month)', 'beta' in A.evaluate("()=>JSON.stringify(JSON.parse(localStorage.getItem('fk3')).reports.mobacklog||{})"))
    if A.locator('#xdlg').count(): A.click('#xdlg button:text-is("Cancel")')
    # settings, on the dashboard
    dash(A); A.click('#cpsettings'); A.wait_for_timeout(300); A.locator('#xdlg input[type=number]').first.fill('10'); A.click('#xdlg button:text-is("Save")'); A.wait_for_timeout(700)
    ok('C12 changing points per person updates the capacity (4 x 10 x 70% = 28)', A.locator('#cproom tr[data-lane="be"] td').nth(1).locator('b').inner_text().endswith('/ 28'))
    # team: leave and leaving
    dash(A)
    names=A.locator('#cp-team .cpperson .cpname').all_inner_texts()
    ok('T1 the team shows all 22 seats with their names', len(names)==22 and 'Altramsi' in names and 'Dina Sam' in names and 'Hamid' in names)
    ok('T2 Khalid is shown in two tracks with an "Also in" note', A.locator('#cp-team .cpperson[data-name="Khalid"]').count()==2 and 'Also in' in A.locator('#cp-team .cpcard[data-lane="pm"] .cpperson[data-name="Khalid"]').inner_text())
    A.click('#cpsettings'); A.wait_for_timeout(300)
    A.locator('#xdlg input[aria-label="Leaving"]').fill('Adnan: 2026-11-20, Mona: 2026-10-01, Zahran: 2027-06-30'); A.click('#xdlg button:text-is("Save")'); A.wait_for_timeout(700)
    ad=A.locator('#cp-team .cpperson[data-name="Adnan"]').inner_text(); mo=A.locator('#cp-team .cpperson[data-name="Mona"]').inner_text(); za=A.locator('#cp-team .cpperson[data-name="Zahran"]').inner_text()
    ok('T3 someone leaving within 60 days is marked "Leaving ... (soon)"', 'Leaving' in ad and '(soon)' in ad)
    ok('T4 someone who has left is marked "Left on"', 'Left on' in mo)
    ok('T5 a far departure shows the date without "soon"', 'Leaving' in za and '(soon)' not in za)
    ok('T6 Quality shows one person not available (Mona left)', A.locator('#cp-team .cpcard[data-lane="qa"] .cpsub').inner_text().startswith('4 people') and 'not available' in A.locator('#cp-team .cpcard[data-lane="qa"] .cpsub').inner_text())
    ok('T7 Quality capacity of November counts three people (3 x 10 x 70% = 21)', A.locator('#cproom tr[data-lane="qa"] td').nth(1).locator('b').inner_text().endswith('/ 21'))
    A.click('#cpsettings'); A.wait_for_timeout(300); A.locator('#xdlg input[aria-label="Leaving"]').fill('Nobody: 2026-11-20'); A.click('#xdlg button:text-is("Save")'); A.wait_for_timeout(300)
    ok('T8 a name that is not in a track is refused with a clear message', 'must be in a track' in A.locator('#xdlg').inner_text()); A.click('#xdlg button:text-is("Cancel")'); A.wait_for_timeout(200)
    # leave from the Vacations page shows on the team card
    A.evaluate("()=>{const s=JSON.parse(localStorage.getItem('fk3')); s.vacations['v1']={p:'Amal Hassan',a0:'2026-10-19',a1:'2026-10-22',t:'Annual',n:''}; s.vacations['v2']={p:'Sayeh',a0:'2026-11-03',a1:'2026-11-05',t:'Annual',n:''}; localStorage.setItem('fk3',JSON.stringify(s));}")
    A.reload(); A.wait_for_timeout(1500); dash(A)
    ok('T9 a person on leave today shows "On leave until"', 'On leave until' in A.locator('#cp-team .cpperson[data-name="Amal"]').inner_text())
    ok('T10 a coming leave shows its dates', 'Leave Tue 3 Nov' in A.locator('#cp-team .cpperson[data-name="Sayeh"]').inner_text())
    ok('T11 leave lowers the November capacity of Full Stack FE (below 28 for the three people)', float(A.locator('#cproom tr[data-lane="fe"] td').nth(1).locator('b').inner_text().split('/')[1])<21.0)
    ok('D1 the module is called Dashboard in the menu and as the page title', A.locator('#nav button[data-p="capacity"]').get_attribute('title')=='Dashboard' and A.locator('#pg-capacity h1').inner_text()=='Dashboard' and A.locator('#cpsettings').inner_text()=='Dashboard settings')
    A.select_option('#cpmonth','2026-11'); A.wait_for_timeout(300)
    ok('D2 the team shows what each person has planned in the chosen month', A.locator('#cp-team .cpperson[data-name="Soliman"] .cpload').inner_text().startswith('8 /') and A.locator('#cp-team .cpperson[data-name="Wardany"] .cpload').inner_text().startswith('5 /'))
    ok('D3 a person over what they can take is flagged and listed under what needs fixing', 'has too many points' in A.locator('#cp-fix').inner_text() and A.locator('#cp-team .cpperson[data-name="Soliman"] .cpload.bad').count()==1)
    A.select_option('#cpmonth','2026-12'); A.wait_for_timeout(300)
    ok('D4 another month shows other loads (Soliman 0 in December)', A.locator('#cp-team .cpperson[data-name="Soliman"] .cpload').inner_text().startswith('0 /'))
    E.reload(); E.wait_for_timeout(1500); dash(E)
    ok('C13 executives see the dashboard but cannot change settings', E.locator('#cproom tbody tr').count()==7 and E.locator('#cpsettings').count()==0 and E.locator('#cp-team .cpperson').count()==22)
